diff --git a/features/support/steps.js b/features/support/steps.js
index 394f0f9..8c4c98b 100644
--- a/features/support/steps.js
+++ b/features/support/steps.js
@@ -318,3 +318,83 @@ Then('the {string} filter link is selected', function (name) {
   if (!link) throw new Error('no filter link "' + name + '"');
   if (!link.classList.contains('selected')) throw new Error('"' + name + '" filter link is not selected');
 });
+
+// ---- conformance: empty-edit removal safety ---------------------------------
+// A @conformance scenario that scans js/app.js for an unguarded removeChild on a stale list
+// item. An empty edit commits its removal through both the edit blur handler and the keydown
+// handler, so render may run twice over the same change; a stale item an earlier render already
+// detached must never reach a removeChild that throws NotFoundError. This is a bespoke
+// conformance checker: no independent tool expresses the constraint, and it asserts real source
+// structure, so it is verification support under QM, not a test double.
+
+const fs = require('node:fs');
+const path = require('node:path');
+
+function sourceAt(rel) {
+  const p = path.resolve(__dirname, '..', '..', rel);
+  if (!fs.existsSync(p)) throw new Error('conformance: source not found at "' + rel + '"');
+  return fs.readFileSync(p, 'utf8');
+}
+
+// Body ranges of every `if (cond)` whose condition references `needle`, so a call inside such a
+// body is treated as guarded. Bodies may be braced `{...}` or a single following statement `;`.
+function guardedRanges(src, needle) {
+  const ranges = [];
+  const re = /(?:^|[^.\w])if\s*\(/g;
+  let m;
+  while ((m = re.exec(src)) !== null) {
+    const parenAt = m.index + m[0].length - 1; // index of '('
+    let depth = 0, condEnd = -1;
+    for (let i = parenAt; i < src.length; i++) {
+      if (src[i] === '(') depth++;
+      else if (src[i] === ')') { depth--; if (depth === 0) { condEnd = i; break; } }
+    }
+    if (condEnd === -1) continue;
+    const cond = src.slice(parenAt + 1, condEnd);
+    if (cond.indexOf(needle) === -1) continue;
+    let j = condEnd + 1;
+    while (j < src.length && /\s/.test(src[j])) j++;
+    if (src[j] === '{') {
+      let bdepth = 0, bodyStart = j + 1;
+      for (let k = j; k < src.length; k++) {
+        if (src[k] === '{') bdepth++;
+        else if (src[k] === '}') { bdepth--; if (bdepth === 0) { ranges.push([bodyStart, k]); break; } }
+      }
+    } else {
+      let k = j;
+      while (k < src.length && src[k] !== ';') k++;
+      ranges.push([j, k]);
+    }
+  }
+  return ranges;
+}
+
+// Find removeChild calls on a list item (the `X.parentNode.removeChild(...)` form) that are not
+// inside a parentNode-guarded if body. Such a call would throw on an already-detached node.
+function unguardedRemovalCalls(src) {
+  const guards = guardedRanges(src, 'parentNode');
+  const unguarded = [];
+  const re = /\.parentNode\.removeChild\(/g;
+  let m;
+  while ((m = re.exec(src)) !== null) {
+    const callAt = m.index;
+    const inside = guards.some(([s, e]) => callAt >= s && callAt <= e);
+    if (!inside) unguarded.push(callAt);
+  }
+  return unguarded;
+}
+
+Given('the app source at {string}', function (rel) {
+  this.conformanceSource = sourceAt(rel);
+});
+
+When('the verifier checks the edit-commit removal path', function () {
+  if (!this.conformanceSource) throw new Error('conformance: no source loaded; run the "the app source at" step first');
+  this.unguardedRemovals = unguardedRemovalCalls(this.conformanceSource);
+});
+
+Then('no removeChild is issued on a list item without a connectivity guard', function () {
+  const bad = this.unguardedRemovals || [];
+  if (bad.length > 0)
+    throw new Error('found ' + bad.length + ' unguarded removeChild call(s) on a list item: a stale, already-detached node would reach a throwing removeChild');
+});
